# Function to add text via API
add_text_via_api() {
    local text="$1"
    response=$(python3 -c "
import sys
import requests
text = sys.argv[1]
response = requests.post('$API_BASE_URL/add_text', json={'text': text})
if response.status_code == 200:
    data = response.json()
    print(f'Added: {text[:30]}... (ID: {data[\"id\"]})')
else:
    print(f'Failed: {response.status_code} {response.text}')
" "$text")
    echo "$response"
}

# Delete all existing texts
echo "Deleting all existing texts..."
response=$(python3 -c "
import requests
response = requests.delete('$API_BASE_URL/delete_all_texts')
if response.status_code == 200:
    print('All texts deleted successfully')
else:
    print(f'Failed to delete: {response.status_code} {response.text}')
")

# Add topic texts
echo "Adding food and sports topic texts..."
for text in "${topic_texts[@]}"; do
    add_text_via_api "$text"
done

echo "Sample data addition complete!"